{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "의심스러운 처방을 확인하지 않은 채 수행하지 않고 담당자에게 확인하는 행동을 검증한다. 투약을 보류한 뒤 담당의에게 실제로 요청한 확인 내용에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 입력되어 투약 전 확인이 필요했던 상황이다.",
          "task": "처방 용량의 적정성이 확인되기 전 투약을 보류하고 담당의에게 처방 의도를 확인해야 했다.",
          "action": "담당의에게 해당 처방과 평소 용량의 차이를 알리고, 입력된 용량이 의도한 처방인지 확인을 요청한 실제 내용을 설명한다.",
          "result": "담당의의 확인으로 입력 오류 여부가 밝혀지는 등 의심했던 처방의 불확실성이 해소된 결과를 설명한다."
        },
        "expectedEvidence": [
          "담당의에게 실제로 확인을 요청한 내용",
          "확인이 필요했던 처방 용량과 의심한 지점",
          "처방이 확인되기 전 투약을 보류했다는 행동",
          "확인 요청에 대한 담당의의 답변과 처방 확인 결과"
        ]
      },
      "question": "푸른결종합병원에서 진통제 처방 용량이 평소 용량의 두 배라 투약을 멈추셨던데요, 그때 담당의에게 어떤 확인을 요청하셨어요?",
      "answerTip": "기억나는 장면을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "담당의에게 알린 용량의 차이와 확인을 요청한 내용을 구체적으로 설명한다.",
            "처방 확인 전 투약을 보류했으며, 담당의의 답변을 통해 입력 오류 여부를 확인한 흐름이 명확하다."
          ]
        },
        "acceptable": {
          "criteria": [
            "투약을 보류하고 담당의에게 용량을 확인했다는 핵심 행동은 드러난다.",
            "실제로 요청한 확인 내용이나 담당의의 답변이 포괄적으로 제시되어 확인 과정의 구체성이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "주의해서 투약해야 한다는 원칙만 말하고 담당의에게 실제로 요청한 확인 내용을 제시하지 못한다.",
            "의심스러운 처방을 확인 전에 수행했거나, 의심한 용량을 담당자에게 확인하는 행동이 드러나지 않는다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "관찰한 환자 상태의 변화를 간호 기록에 정확히 남기는 행동을 검증한다. 수술 후 환자의 이전 상태와 이후 변화가 드러나도록 실제로 기록한 내용에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "정형외과 병동에서 수술 후 환자의 활력징후와 통증을 관찰하고 간호 기록을 작성했던 상황이다.",
          "task": "관찰한 환자 상태가 시간에 따라 어떻게 달라졌는지 기록으로 확인할 수 있도록 남겨야 했다.",
          "action": "실제로 기록한 관찰 시점과 상태를 설명하고, 이전 관찰과 비교해 달라진 부분을 어떤 내용으로 남겼는지 제시한다.",
          "result": "기록된 내용을 통해 환자 상태의 변화 시점과 양상을 파악할 수 있다. 보고나 인수인계 수행 여부는 이 질문의 필수 평가 조건으로 삼지 않는다."
        },
        "expectedEvidence": [
          "환자 상태의 변화가 드러나도록 실제 간호 기록에 남긴 내용",
          "해당 기록의 바탕이 된 활력징후 또는 통증 관찰 사실",
          "이전 상태와 이후 상태를 구분할 수 있는 관찰 시점과 변화 내용",
          "관찰한 사실과 기록 내용의 일치 여부"
        ]
      },
      "question": "푸른결종합병원에서 수술 후 환자의 활력징후와 통증을 관찰하셨던데요, 그때 환자 상태의 변화가 드러나도록 간호 기록에 남긴 내용은 무엇이었어요?",
      "answerTip": "한 사례를 골라 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실제로 기록한 내용을 구체적으로 제시하고, 그 내용이 관찰한 환자 상태와 일치한다.",
            "관찰 시점과 이전 대비 변화가 명확해 기록만으로 환자 상태의 변화 양상을 파악할 수 있다."
          ]
        },
        "acceptable": {
          "criteria": [
            "관찰한 상태 변화를 기록한 내용은 제시하지만, 관찰 시점이나 이전 상태와의 비교가 일부 불명확하다.",
            "기록과 관찰 사실의 연결은 드러나지만 실제 기록 내용의 구체성이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "기록을 꼼꼼히 했다는 설명만 있고 실제로 남긴 환자 상태 변화의 내용이 없다.",
            "관찰한 사실과 기록이 맞지 않거나, 기록 내용으로 환자 상태의 변화를 파악하기 어렵다."
          ]
        }
      }
    }
  ]
}
